const uid=()=>crypto.randomUUID();
const oneLine=(value:string)=>value.replace(/[\r\n\u0000-\u001f\u007f]/g,' ').trim().slice(0,500);
const validEmail=(value:string)=>value.length<=254&&/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(value);
const privilegedTypeFromUsername=(value:string)=>{const clean=oneLine(value),separator=clean.lastIndexOf('_');return separator>0&&separator<clean.length-1?clean.slice(separator+1):''};
const parsePrivilegedUsernames=(value:string)=>Array.from(new Set(value.split(',').map(item=>oneLine(item)).filter(Boolean))).slice(0,50);
const privilegedTypesFromUsernames=(values:string[])=>Array.from(new Set(values.map(privilegedTypeFromUsername).filter(Boolean)));
