type SaarReadResult={email:string;identity?:SaarIdentity;organization?:string;format?:'AcroForm'|'XFA';pdfName?:string;error?:string;manualEntryAllowed?:boolean};
async function readSaarFile(source:File):Promise<SaarReadResult>{
 try{
  if(source.size>evidenceFileLimit)return{email:'',error:'The SAAR exceeds the 100 MB file limit.'};
  const inspected=inspectEvidenceBytes(source.name,new Uint8Array(await source.arrayBuffer())),fields=await readSaarFormFields(inspected.pdfBytes);
  if(!fields.fillable)return{email:'',error:'The SAAR is not a supported fillable AcroForm or DD2875 XFA PDF.'};
  const email=oneLine(fields.email??''),base={email,identity:fields.identity,organization:fields.organization,format:fields.format,pdfName:inspected.pdfName};
  return validEmail(email)?base:{...base,email:'',error:'The SAAR Official Email field is empty or invalid.',manualEntryAllowed:true};
 }catch{return{email:'',error:'The SAAR is not a readable fillable PDF.'}}
}
async function readSaar(handle?:EvidenceHandle,signal?:AbortSignal){
 if(!handle)return{email:'',error:'The SAAR file could not be opened.'};
 try{throwIfSyncCancelled(signal);return await readSaarFile(await evidenceFile(handle,signal))}catch{throwIfSyncCancelled(signal);return{email:'',error:'The SAAR file could not be opened.'}}
}
function newestMatch<T>(items:T[],kind:string,nameOf:(item:T)=>string){let match:T|undefined,newest=-Infinity;for(const item of items){const name=nameOf(item);if(!filenameMatchesKind(name,kind))continue;const time=parseDate(name)?.getTime();if(time!==undefined&&time>newest){match=item;newest=time}}return match}
