async function portableFile(ref:PortableFileRef,signal?:AbortSignal){const response=await portableRequest({kind:'portable',systemId:ref.systemId,name:''},`file?path=${encodeURIComponent(ref.path)}`,{signal}),bytes=await response.arrayBuffer();return new File([bytes],ref.name)}
