async function launcherPost(path:string,keepalive=false){if(!trackerWindow().__portableHost)return;try{await fetch(path,{method:'POST',credentials:'same-origin',cache:'no-store',keepalive})}catch{}}
let backupWriteChain=Promise.resolve();
let lastAuditError='';
function trackedBackupWrite<T>(operation:()=>Promise<T>){const queued=backupWriteChain.then(async()=>{if(trackerWindow().__portableHost)await launcherPost('/api/backup-dirty',true);try{const result=await operation();if(trackerWindow().__portableHost)await launcherPost('/api/backup-complete',true);return result}catch(error){if(trackerWindow().__portableHost)await launcherPost('/api/backup-failed',true);throw error}});backupWriteChain=queued.then(()=>undefined,()=>undefined);return queued}
type SessionLease={sessionId:string;actor:string;updated:string;released?:boolean};
async function readLease(root:StorageRoot){if(isPortableRoot(root))return null;try{const handle=await root.getFileHandle(leaseFile),file=await handle.getFile();if(file.size>16*1024)throw new Error('Session lease exceeds the size limit.');const value=JSON.parse(await file.text()) as Partial<SessionLease>;if(typeof value.sessionId==='string'&&value.sessionId.length<=100&&typeof value.actor==='string'&&value.actor.length<=500&&typeof value.updated==='string'&&value.updated.length<=50)return value as SessionLease}catch(error){if(!(error instanceof DOMException&&error.name==='NotFoundError'))console.error('Unable to read session lease',error)}return null}
async function writeLease(root:FileSystemDirectoryHandle,lease:SessionLease){const handle=await root.getFileHandle(leaseFile,{create:true}),writer=await handle.createWritable();await writer.write(JSON.stringify(lease,null,2));await writer.close()}
async function acquireLease(root:StorageRoot,sessionId:string){if(isPortableRoot(root)){const response=await portableRequest(root,`lease-acquire?session=${encodeURIComponent(sessionId)}`,{method:'POST'}),result=await response.json() as{acquired?:boolean};return result.acquired===true}const current=await readLease(root),fresh=current&&!current.released&&Date.now()-Date.parse(current.updated)<leaseStaleMs;if(fresh&&current.sessionId!==sessionId)return false;await writeLease(root,{sessionId,actor:currentActor(),updated:new Date().toISOString()});const verified=await readLease(root);return verified?.sessionId===sessionId&&!verified.released}
