async function releaseLease(root:StorageRoot,sessionId:string){if(isPortableRoot(root)){await portableRequest(root,`lease-release?session=${encodeURIComponent(sessionId)}`,{method:'POST'});return}const current=await readLease(root);if(current?.sessionId===sessionId)await writeLease(root,{...current,updated:new Date().toISOString(),released:true})}
async function requireActiveLease(root:StorageRoot){const sessionId=(window as unknown as{__trackerSessionId?:string}).__trackerSessionId;if(!sessionId||!(await renewLease(root,sessionId)))throw new Error('This tracker session is disconnected because another operator is active.')}
async function verifyBrowserAudit(directory:FileSystemDirectoryHandle){const names:string[]=[];for await(const[name,entry]of(directory as DirectoryWithEntries).entries()){if(entry.kind!=='file'||!name.startsWith('audit-')||!name.endsWith('.jsonl'))continue;if(!/^audit-\d{4}-\d{2}-\d{2}\.jsonl$/.test(name))throw new Error('An audit-log filename is invalid.');names.push(name)}if(names.length>10000)throw new Error('The audit-log file count exceeds the verification limit.');let state:AuditChainState={entries:0,headHash:auditGenesisHash};const recent:AuditEntry[]=[];for(const name of names.sort()){const handle=await directory.getFileHandle(name),file=await handle.getFile();if(file.size<=0||file.size>100*1024*1024)throw new Error(`${name} is empty or exceeds the audit-log size limit.`);const text=await file.text();state=await verifyAuditText(text,state,name.slice(6,16));for(const line of text.split(/\r?\n/).filter(Boolean)){recent.push(JSON.parse(line) as AuditEntry);if(recent.length>500)recent.shift()}}return{...state,files:names.length,legacyFiles:0,recent:recent.reverse()}}
async function appendAudit(action:string,systemId=trackerWindow().__activeSystemId){const h=rootFor(systemId);if(!h){lastAuditError='';return true}try{if(isPortableRoot(h)){await portableRequest(h,'audit',{method:'POST',body:oneLine(action)});lastAuditError='';return true}const dir=await h.getDirectoryHandle('Audit Logs',{create:true}),state=await verifyBrowserAudit(dir),entry=await buildAuditEntry(state,currentActor(),action),day=entry.timestampUtc.slice(0,10),file=await dir.getFileHandle(`audit-${day}.jsonl`,{create:true}),existing=await file.getFile(),w=await file.createWritable({keepExistingData:true});await w.write({type:'write',position:existing.size,data:`${JSON.stringify(entry)}\n`});await w.close();lastAuditError='';return true}catch(error){lastAuditError=oneLine(error instanceof Error?error.message:'The audit log could not be verified or extended.');console.error('Unable to write or verify audit log',error);return false}}
function warnAuditFailure(ok:boolean){if(!ok)alert(`The action completed, but the tamper-evident audit log could not be verified or extended. Stop making changes and check the mapped shared folder.${lastAuditError?`\n\nDetails: ${lastAuditError}`:''}`)}
function safeCsv(value:string){const clean=oneLine(String(value));return /^[=+\-@\t]/.test(clean)?`'${clean}`:clean}
function csvRows(users:UserRecord[],systems:SystemRecord[],kinds:string[]=artifactKinds,state='all'){const rows=[['Last name','First name','Email','Organization','Information system','System status','User status','Roles','Privileged username','Privileged user type','Artifact','Status','Filename']];users.forEach(u=>requiredKinds(u).filter(k=>kinds.includes(k)).forEach(k=>{const status=statusFor(u,k);if(state!=='all'&&status!==state)return;const s=systems.find(x=>x.id===u.systemId);rows.push([u.last,u.first,u.email,u.organization,s?.name||'',s?.archived?'Archived':'Active',u.disabled?'Disabled':'Active',u.roles.join('; '),u.privilegedUsernames.join('; '),u.privilegedTypes.join('; '),k,status,newestArtifactFor(u,k)?.filename||''])}));return rows.map(r=>r.map(v=>`"${safeCsv(v).replaceAll('"','""')}"`).join(',')).join('\n')}
function filteredDirectoryCsvRows(users:UserRecord[],system:SystemRecord,artifactFilter:string,statusFilter:string,asOf:Date){const rows=[['Last name','First name','Official email','Organization','Information system','User status','Roles','Privileged username','Privileged user type','Artifact','Status','Days overdue','Days until due','Filename']];for(const user of users){const kinds=artifactFilter==='All artifacts'?requiredKinds(user):requiredKinds(user).includes(artifactFilter)?[artifactFilter]:[];for(const kind of kinds){const filterStatus=directoryStatusFor(user,kind,asOf);if(statusFilter!=='All statuses'&&filterStatus!==statusFilter)continue;const overdueDays=filterStatus==='Overdue'?daysOverdueFor(user,kind,asOf):0,dueDays=filterStatus==='Due Within 30 Days'?daysUntilDueFor(user,kind,asOf)??0:0,status=filterStatus==='Overdue'?`Overdue ${overdueDays} Day${overdueDays===1?'':'s'}`:filterStatus==='Due Within 30 Days'?`Due in ${dueDays} Day${dueDays===1?'':'s'}`:filterStatus;rows.push([user.last,user.first,user.email,user.organization,system.name,user.disabled?'Disabled':'Active',user.roles.join('; '),user.privilegedUsernames.join('; '),user.privilegedTypes.join('; '),kind,status,String(overdueDays||''),String(dueDays||''),newestArtifactFor(user,kind)?.filename||''])}}return{rowCount:rows.length-1,csv:rows.map(row=>row.map(value=>`"${safeCsv(value).replaceAll('"','""')}"`).join(',')).join('\n')}}
async function writeTextFile(directory:FileSystemDirectoryHandle,name:string,text:string){const file=await directory.getFileHandle(name,{create:true}),writer=await file.createWritable();await writer.write(text);await writer.close()}
async function readBrowserSyncIndex(root:FileSystemDirectoryHandle,forceFull:boolean){
 if(forceFull)return new Map<string,SyncIndexEntry>();
 try{
  const indexHandle=await root.getFileHandle(syncIndexFilename),indexFile=await indexHandle.getFile();if(indexFile.size<=0||indexFile.size>50*1024*1024)return new Map<string,SyncIndexEntry>();
  const text=await indexFile.text(),checksumHandle=await root.getFileHandle(syncIndexChecksumFilename),checksumFile=await checksumHandle.getFile();if(checksumFile.size<=0||checksumFile.size>1024)return new Map<string,SyncIndexEntry>();
  const expected=checksumFromText(await checksumFile.text(),syncIndexFilename);if(!expected||await sha256Bytes(new TextEncoder().encode(text))!==expected)return new Map<string,SyncIndexEntry>();
  const parsed=readSyncIndex(JSON.parse(text),complianceRuleSetVersion);return new Map((parsed?.files??[]).map(entry=>[syncIndexKey(entry.path),entry]));
 }catch(error){if(!(error instanceof DOMException&&error.name==='NotFoundError'))console.warn('The shared Sync index could not be reused; this Sync will validate every evidence file.',error);return new Map<string,SyncIndexEntry>()}
}
async function writeBrowserSyncIndex(root:FileSystemDirectoryHandle,files:SyncIndexEntry[]){
 const text=JSON.stringify(createSyncIndex(complianceRuleSetVersion,files)),bytes=new TextEncoder().encode(text);if(bytes.byteLength>50*1024*1024)throw new Error('The shared Sync index exceeds the 50 MB safety limit.');
 await writeTextFile(root,syncIndexFilename,text);try{const hash=await sha256Bytes(bytes);await writeTextFile(root,syncIndexChecksumFilename,`${hash}  ${syncIndexFilename}\n`)}catch(error){await root.removeEntry(syncIndexFilename).catch(()=>undefined);throw error}
}
async function snapshotNames(directory:FileSystemDirectoryHandle){const names:string[]=[];for await(const[name,entry]of(directory as DirectoryWithEntries).entries())if(entry.kind==='file'&&/^user-tracker-\d{4}-\d{2}-\d{2}T.+Z\.json$/.test(name))names.push(name);return names.sort().reverse()}
