async function readVerifiedBackup(root:FileSystemDirectoryHandle,filename:string,systemId:string){const directory=await root.getDirectoryHandle('backup'),handle=await directory.getFileHandle(filename),file=await handle.getFile();if(file.size>50*1024*1024)throw new Error('The backup exceeds the 50 MB safety limit.');const text=await file.text(),checksumHandle=await directory.getFileHandle(checksumFilename(filename)),checksumFile=await checksumHandle.getFile();if(checksumFile.size>1024)throw new Error('The backup checksum file is invalid.');const expected=checksumFromText(await checksumFile.text(),filename);if(!expected)throw new Error('The matching SHA-256 checksum file is missing or invalid.');const envelope=await verifyBackupSnapshot(text,expected),normalized=normalizeManifest(envelope.database);if(!normalized||normalized.systems.length!==1||normalized.systems[0].id!==systemId)throw new Error('The backup does not contain a valid snapshot for the selected information system.');return{created:envelope.created,data:stripDemoData(normalized)}}
