   async function selectInformationSystem(systemId:string){if(syncAbort.current){alert('Stop the current Sync before changing information systems.');return}const previous=trackerWindow().__activeSystemId;if(previous&&previous!==systemId){const previousRoot=rootFor(previous);if(previousRoot&&sessionState==='active'){try{await writeSystemManifest(previousRoot,previous,systems,users);await releaseLease(previousRoot,sessionId)}catch(error){setSessionMessage(error instanceof Error?`The current system could not be safely released: ${error.message}`:'The current system could not be safely released.');setSessionState('blocked');return}}}setSelected(systemId);setPendingSync(pendingSyncBySystem.current.get(systemId)??null);trackerWindow().__activeSystemId=systemId;resetFilters();const root=rootFor(systemId);if(!root){setSessionState('unmapped');setSessionMessage('');return}if(await acquireLease(root,sessionId)){lastActivity.current=Date.now();setSessionState('active');setSessionMessage('');await syncMapped(systemId,root,systems,users)}else{setSessionState('blocked');setSessionMessage('Another operator has an exclusive lock on this system folder. Try again after that operator disconnects.')}}
