 async function openRestore(){const systemId=effectiveSelected,root=rootFor(systemId);if(!root){alert('Map the selected information system folder before restoring a backup.');return}setRestoreCandidates([]);setRestoreLoading(true);setModal('restore');try{if(isPortableRoot(root)){const response=await portableRequest(root,`backups?logical=${encodeURIComponent(systemId)}`);setRestoreCandidates(await response.json() as RestoreCandidate[])}else setRestoreCandidates(await listRestoreCandidates(root,systemId))}catch(error){alert(error instanceof Error?error.message:'Unable to read the backup folder.');setModal(null)}finally{setRestoreLoading(false)}}
